/* @lc app=leetcode id=2115 lang=kotlin */ class Solution { fun findAllRecipes(recipes: Array<String>, ingredients: List<List<String>>, supplies: Array<String>): List<String> = java.util.HashMap<String, Int>().let { deg -> java.util.HashMap<String, MutableList<String>>().let { adj -> recipes.indices.forEach { i -> deg[recipes[i]] = ingredients[i].size.also { ingredients[i].forEach { ing -> adj.getOrPut(ing) { mutableListOf() }.add(recipes[i]) } } }.let { java.util.ArrayDeque<String>().also { q -> supplies.forEach { q.add(it) } } }.let { q -> mutableListOf<String>().also { ans -> while (!q.isEmpty()) q.poll().let { curr -> adj[curr]?.forEach { recipe -> deg[recipe] = (deg[recipe]!! - 1).also { if (deg[recipe] == 0) q.add(recipe).also { ans.add(recipe) } } } } } } } } }